import React, { useState, useEffect } from 'react';
import { DragDropContext } from 'react-beautiful-dnd';
import axios from 'axios';
import TaskColumn from './components/TaskColumn';
import NewTaskModal from './components/NewTaskModal';
import './App.css';

function App() {
  const [tasks, setTasks] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    fetchTasks();
  }, []);

  const fetchTasks = async () => {
    try {
      const response = await axios.get('http://localhost:5001/api/tasks');
      setTasks(response.data);
    } catch (error) {
      console.error('Error fetching tasks:', error);
    }
  };

  const handleDragEnd = async (result) => {
    if (!result.destination) return;

    const { source, destination, draggableId } = result;
    if (source.droppableId === destination.droppableId) return;

    try {
      await axios.patch(`http://localhost:5001/api/tasks/${draggableId}`, {
        status: destination.droppableId
      });
      fetchTasks();
    } catch (error) {
      console.error('Error updating task status:', error);
    }
  };

  const handleNewTask = async (title) => {
    try {
      await axios.post('http://localhost:5001/api/tasks', { title });
      fetchTasks();
      setIsModalOpen(false);
    } catch (error) {
      console.error('Error creating task:', error);
    }
  };

  return (
    <div className="app">
      <div className="container">
        <div className="header">
          <h1>Task Board</h1>
          <button className="new-task-button" onClick={() => setIsModalOpen(true)}>
            New Task
          </button>
        </div>

        <DragDropContext onDragEnd={handleDragEnd}>
          <div className="columns">
            <TaskColumn
              title="To Do"
              tasks={tasks.filter(task => task.status === 'todo')}
              status="todo"
            />
            <TaskColumn
              title="In Progress"
              tasks={tasks.filter(task => task.status === 'inprogress')}
              status="inprogress"
            />
            <TaskColumn
              title="Done"
              tasks={tasks.filter(task => task.status === 'done')}
              status="done"
            />
          </div>
        </DragDropContext>

        <NewTaskModal
          isOpen={isModalOpen}
          onClose={() => setIsModalOpen(false)}
          onSubmit={handleNewTask}
        />
      </div>
    </div>
  );
}

export default App;
